import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import http from 'node:http';
import {open} from '../../src/index.ts';
import {EphemeralIndexCursor,PrivateStateByteBudget} from '../../src/internal/private-state.ts';
const sql='SELECT a, sum(d) OVER (ORDER BY d ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM t1';
test('bounded ordinary ROWS returns with source pending-end lookahead, evicts inverse rows, measures peak',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});
 await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const insert=EphemeralIndexCursor.prototype.insert,reserve=PrivateStateByteBudget.prototype.reserve,del=EphemeralIndexCursor.prototype.deleteCurrent;
 EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};
 const native=JSON.parse(fs.readFileSync('docs/research/card-s-i/window-overlap-decision-native.json'));
 let inserts=0,peak=0,deletes=0;const budgets=new Set();
 EphemeralIndexCursor.prototype.insert=async function(...args){await insert.apply(this,args);inserts++;};
 PrivateStateByteBudget.prototype.reserve=function(...args){budgets.add(this);reserve.apply(this,args);peak=Math.max(peak,this.usedBytes);};
 let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare(sql).statement;
 assert.equal(await stmt.step(),'row');assert.equal(inserts,3,'source initializes first row, then steps previous end at next input');
 const rows=[Array.from({length:stmt.columnCount},(_,i)=>({type:stmt.columnType(i),value:String(stmt.column(i))}))];while(await stmt.step()==='row')rows.push(Array.from({length:stmt.columnCount},(_,i)=>({type:stmt.columnType(i),value:String(stmt.column(i))})));assert.deepEqual(rows,native.rows);assert.equal(deletes,4,'flush returns final current before EOF break: no final inverse/delete');assert.equal(peak,359);console.log('corrected observed accounted peak',peak);
 stmt.finalize();db.closeDeferred();db=null;stmt=null;assert.ok([...budgets].every(b=>b.usedBytes===0));
 for(const cap of [200,335,336,358,359,360]){db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`),{limits:{maxPrivateBytes:cap}});stmt=db.prepare(sql).statement;
 if(cap<359){let saved;await assert.rejects(async()=>{while(await stmt.step()==='row'){}},e=>{saved=e;return e.kind==='limit'});assert.throws(()=>stmt.reset(),e=>e===saved);}else{let count=0;while(await stmt.step()==='row')count++;assert.equal(count,6);stmt.reset();count=0;while(await stmt.step()==='row')count++;assert.equal(count,6);}
 try{stmt.finalize()}catch{}db.closeDeferred();db=null;stmt=null;assert.ok([...budgets].every(b=>b.usedBytes===0));}
 }finally{EphemeralIndexCursor.prototype.insert=insert;PrivateStateByteBudget.prototype.reserve=reserve;EphemeralIndexCursor.prototype.deleteCurrent=del;try{stmt?.finalize()}catch{}try{db?.closeDeferred()}catch{}await new Promise(r=>s.close(r));}
});
test('bounded shared aggregate frame keeps typed payloads in all encodings, partition drains and empty input',async()=>{
 const s=http.createServer((req,res)=>{const name=req.url.slice(1);const file=`test/fixtures/aggregate-window/${name}.db`;res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 async function run(name,sql){const db=await open(new Request(`http://127.0.0.1:${s.address().port}/${name}`));const stmt=db.prepare(sql).statement;try{const rows=[];while(await stmt.step()==='row')rows.push(Array.from({length:stmt.columnCount},(_,i)=>stmt.column(i)));return rows;}finally{stmt.finalize();db.closeDeferred();}}
 try{
 for(const name of ['typed','typed-utf-16le','typed-utf-16be']){
 const rows=await run(name,'SELECT i,r,t,b,n,sum(r) OVER (ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING),count(i) OVER (ORDER BY i ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM t');
 assert.deepEqual(rows.map(r=>r.slice(0,3)),[[1n,1,'A'],[2n,2.5,'a'],[3n,3,null]]);
 assert.deepEqual(rows.map(r=>r.slice(4)),[[null,3.5,2n],[null,6.5,3n],[null,5.5,2n]]);assert.deepEqual([...rows[0][3]],[0,255]);assert.deepEqual([...rows[1][3]],[]);assert.equal(rows[2][3],null);
 }
 const rows=await run('w2rows','SELECT a,sum(d) OVER (PARTITION BY b ORDER BY d ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) FROM t1');
 assert.deepEqual(rows,[[2n,6n],[4n,12n],[6n,10n],[1n,4n],[3n,9n],[5n,8n]]);
 assert.deepEqual(await run('w2rows',sql+' WHERE a<0'),[]);
 }finally{await new Promise(r=>s.close(r));}
});
test('saved-position delete failure halts with original error and refund every private reservation',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const reserve=PrivateStateByteBudget.prototype.reserve,budgets=new Set();PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 try{
 const original=EphemeralIndexCursor.prototype.deleteCurrent;let calls=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(control){calls++;await control.checkpoint(1);throw new Error('injected saved-position failure');};
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare(sql).statement;let saved;await assert.rejects(async()=>{while(await stmt.step()==='row'){}},e=>{saved=e;return e.message.includes('injected saved-position failure')});assert.equal(calls,1);assert.throws(()=>stmt.reset(),e=>e===saved);assert.ok([...budgets].every(b=>b.usedBytes===0));}finally{EphemeralIndexCursor.prototype.deleteCurrent=original;try{stmt?.finalize()}catch{}db?.closeDeferred();}
 }finally{PrivateStateByteBudget.prototype.reserve=reserve;await new Promise(r=>s.close(r));}
});
test('zero bounds and rebind restart bounded lookahead counters without replay',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER (ORDER BY d ROWS BETWEEN ? PRECEDING AND ? FOLLOWING) FROM t1').statement;
 for(const [start,end,expected] of [[0n,0n,[1n,2n,3n,4n,5n,6n]],[1n,0n,[1n,3n,5n,7n,9n,11n]],[0n,1n,[3n,5n,7n,9n,11n,6n]],[1n,1n,[3n,6n,9n,12n,15n,11n]]]){stmt.bind(1,start);stmt.bind(2,end);const rows=[];while(await stmt.step()==='row')rows.push(stmt.column(1));assert.deepEqual(rows,expected);stmt.reset();}
 }finally{try{stmt?.finalize()}finally{db?.closeDeferred();await new Promise(r=>s.close(r));}}
});
test('abort and deadline at saved-position deletion preserve first error and release shared state',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const reserve=PrivateStateByteBudget.prototype.reserve,del=EphemeralIndexCursor.prototype.deleteCurrent,budgets=new Set();
 PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 try{for(const kind of ['cancelled','timeout']){let calls=0;const controller=new AbortController();
 EphemeralIndexCursor.prototype.deleteCurrent=async function(control){calls++;if(kind==='cancelled')controller.abort();else await new Promise(r=>setTimeout(r,30));return del.call(this,control);};
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare(sql).statement;
 // Reach the first output before testing deadline, so network/producer time is not the fault site.
 assert.equal(await stmt.step(),'row');assert.equal(await stmt.step(),'row');let saved;
 await assert.rejects(stmt.step(kind==='cancelled'?{signal:controller.signal}:{timeoutMs:10}),e=>{saved=e;return e.kind===kind});assert.equal(calls,1);assert.throws(()=>stmt.reset(),e=>e===saved);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{try{stmt?.finalize()}catch{}db?.closeDeferred();}}
 }finally{PrivateStateByteBudget.prototype.reserve=reserve;EphemeralIndexCursor.prototype.deleteCurrent=del;await new Promise(r=>s.close(r));}
});
