test('inverse callback failure precedes deletion, preserves saved error and refunds all state',async()=>{
 const {Mem}=await import('../../src/internal/mem.ts');
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const state=Mem.prototype.aggregateState,del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;
 let armed=false,injected=0,deletes=0;const budgets=new Set();
 Mem.prototype.aggregateState=function(){const value=state.call(this);if(armed&&value?.definition?.name==='sum'&&injected===0){value.context.cnt=0n;injected++;}return value;};
 EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};
 PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare(sql).statement;assert.equal(await stmt.step(),'row');assert.equal(await stmt.step(),'row');armed=true;let saved;
 await assert.rejects(stmt.step(),e=>{saved=e;return e.kind==='internal'&&e.message==='sum inverse without stepped value'});assert.equal(injected,1);assert.equal(deletes,0);assert.throws(()=>stmt.reset(),e=>e===saved);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{Mem.prototype.aggregateState=state;EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
