test('groups current peer frame retires previous peer after output before next output',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const del=EphemeralIndexCursor.prototype.deleteCurrent,insert=EphemeralIndexCursor.prototype.insert;let deletes=0,inserts=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);inserts++;};let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN CURRENT ROW AND CURRENT ROW)').statement;
 assert.equal(await stmt.step(),'row');assert.equal(inserts,2,'new peer admission steps and returns pending peer');const rows=[[stmt.column(0),stmt.column(1),stmt.column(2)]];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,Array.from({length:6},(_,i)=>[BigInt(i+1),BigInt(i+1),1n]));assert.equal(deletes,5,'final current peer EOF skips inverse/delete');
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;EphemeralIndexCursor.prototype.insert=insert;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('groups current peers preserve collation DESC NULL keys, partition reset and typed encoding',async()=>{
 const s=http.createServer((req,res)=>{const file=`test/fixtures/aggregate-window/${req.url.slice(1)}.db`;res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 try{for(const name of ['typed','typed-utf-16le','typed-utf-16be']){const db=await open(new Request(`http://127.0.0.1:${s.address().port}/${name}`));const stmt=db.prepare('SELECT i,r,t,b,n,sum(r) OVER w,count(i) OVER w FROM t WINDOW w AS (ORDER BY t COLLATE NOCASE DESC NULLS FIRST GROUPS BETWEEN CURRENT ROW AND CURRENT ROW)').statement;try{for(let pass=0;pass<2;pass++){const rows=[];while(await stmt.step()==='row')rows.push(Array.from({length:stmt.columnCount},(_,i)=>stmt.column(i)));assert.deepEqual(rows.map(r=>[r[0],r[5],r[6]]),[[3n,3,1n],[1n,3.5,2n],[2n,3.5,2n]]);assert.deepEqual([...rows[1][3]],[0,255]);assert.deepEqual([...rows[2][3]],[]);assert.ok(rows.every(r=>r[4]===null));stmt.reset();}}finally{stmt.finalize();db.closeDeferred();}}
 const db=await open(new Request(`http://127.0.0.1:${s.address().port}/w2rows`));const stmt=db.prepare('SELECT a,sum(d) FILTER (WHERE a>2) OVER w,count(d) OVER w FROM t1 WINDOW w AS (PARTITION BY b ORDER BY b GROUPS BETWEEN CURRENT ROW AND CURRENT ROW)').statement;try{for(let pass=0;pass<2;pass++){const rows=[];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[2n,10n,3n],[4n,10n,3n],[6n,10n,3n],[1n,8n,3n],[3n,8n,3n],[5n,8n,3n]]);stmt.reset();}}finally{stmt.finalize();db.closeDeferred();}
 }finally{await new Promise(r=>s.close(r));}
});
test('groups current post-peer inverse deletion failure preserves output and first error',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));const del=EphemeralIndexCursor.prototype.deleteCurrent;const error=new Error('peer inverse retirement');let hit=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(){hit++;throw error;};let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT sum(d) OVER (ORDER BY d GROUPS BETWEEN CURRENT ROW AND CURRENT ROW) FROM t1').statement;assert.equal(await stmt.step(),'row');assert.equal(stmt.column(0),1n);assert.equal(hit,0);await assert.rejects(stmt.step(),e=>e===error);assert.equal(hit,1);assert.throws(()=>stmt.reset(),e=>e===error);
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});

test('groups current multi-term peer keys include secondary direction, and bounded cache counts',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));let db;const insert=EphemeralIndexCursor.prototype.insert,del=EphemeralIndexCursor.prototype.deleteCurrent;let live=0,max=0;EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);max=Math.max(max,++live);};EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){await del.apply(this,a);live--;};
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));const stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY b,d DESC GROUPS BETWEEN CURRENT ROW AND CURRENT ROW)').statement;try{const rows=[];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[6n,6n,1n],[4n,4n,1n],[2n,2n,1n],[5n,5n,1n],[3n,3n,1n],[1n,1n,1n]]);assert.equal(max,2,'pending peer plus boundary row, not full partition');}finally{stmt.finalize();}
 }finally{EphemeralIndexCursor.prototype.insert=insert;EphemeralIndexCursor.prototype.deleteCurrent=del;db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('range current multi-term peer keys include secondary direction, and bounded cache counts',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));let db;const insert=EphemeralIndexCursor.prototype.insert,del=EphemeralIndexCursor.prototype.deleteCurrent;let live=0,max=0;EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);max=Math.max(max,++live);};EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){await del.apply(this,a);live--;};
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));const stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY b,d DESC RANGE BETWEEN CURRENT ROW AND CURRENT ROW)').statement;try{const rows=[];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[6n,6n,1n],[4n,4n,1n],[2n,2n,1n],[5n,5n,1n],[3n,3n,1n],[1n,1n,1n]]);assert.equal(max,2,'pending peer plus boundary row, not full partition');}finally{stmt.finalize();}
 for(const [query,expected] of [
 ['SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY b,b DESC RANGE BETWEEN CURRENT ROW AND CURRENT ROW)',[[2n,12n,3n],[4n,12n,3n],[6n,12n,3n],[1n,9n,3n],[3n,9n,3n],[5n,9n,3n]]],
 ['SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (PARTITION BY b ORDER BY d DESC,a RANGE BETWEEN CURRENT ROW AND CURRENT ROW)',[[6n,6n,1n],[4n,4n,1n],[2n,2n,1n],[5n,5n,1n],[3n,3n,1n],[1n,1n,1n]]]]){
 const st=db.prepare(query).statement;try{for(let pass=0;pass<2;pass++){const rows=[];while(await st.step()==='row')rows.push([st.column(0),st.column(1),st.column(2)]);assert.deepEqual(rows,expected);st.reset();}}finally{st.finalize();}}
 assert.throws(()=>db.prepare('SELECT sum(d) OVER (ORDER BY b,d RANGE BETWEEN 1 PRECEDING AND CURRENT ROW) FROM t1'),/requires one ORDER BY/);
 }finally{EphemeralIndexCursor.prototype.insert=insert;EphemeralIndexCursor.prototype.deleteCurrent=del;db?.closeDeferred();await new Promise(r=>s.close(r));}
});
