test('groups cumulative offset parameters reset rebind and preserve retention policy',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));let db;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));for(const order of ['d','b']){
 const stmt=db.prepare(`SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY ${order} GROUPS BETWEEN UNBOUNDED PRECEDING AND ?1 PRECEDING)`).statement;
 try{for(const n of [0,1,2,9]){stmt.bind(1,BigInt(n));const rows=[];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);const sequence=order==='d'?[1,2,3,4,5,6]:[2,4,6,1,3,5];assert.deepEqual(rows,sequence.map(a=>{const eligible=sequence.filter(v=>order==='d'?v<=a-n:(v%2===0?0:1)<=(a%2===0?0:1)-n);return [BigInt(a),eligible.length?BigInt(eligible.reduce((x,y)=>x+y,0)):null,BigInt(eligible.length)];}));stmt.reset();}}
 finally{stmt.finalize();}}
 }finally{db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('groups prior countdown typed encodings and source-selected retirement',async()=>{
 const s=http.createServer((req,res)=>{const file=`test/fixtures/aggregate-window/${req.url.slice(1)}.db`;res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));const del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;let deletes=0;const budgets=new Set();EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){await del.apply(this,a);deletes++;};PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 try{for(const name of ['typed','typed-utf-16le','typed-utf-16be']){const db=await open(new Request(`http://127.0.0.1:${s.address().port}/${name}`));try{for(const bound of ['0','1','2','?1']){const stmt=db.prepare(`SELECT i,r,t,b,n,sum(r) OVER w,count(i) OVER w FROM t WINDOW w AS (ORDER BY t COLLATE NOCASE DESC NULLS FIRST GROUPS BETWEEN UNBOUNDED PRECEDING AND ${bound} PRECEDING)`).statement;try{if(bound==='?1')stmt.bind(1,1n);for(let pass=0;pass<2;pass++){deletes=0;const rows=[];while(await stmt.step()==='row')rows.push(Array.from({length:stmt.columnCount},(_,i)=>stmt.column(i)));const values=bound==='0'?[[3n,3,1n],[1n,6.5,3n],[2n,6.5,3n]]:bound==='2'?[[3n,null,0n],[1n,null,0n],[2n,null,0n]]:[[3n,null,0n],[1n,3,1n],[2n,3,1n]];assert.deepEqual(rows.map(r=>[r[0],r[5],r[6]]),values);assert.deepEqual([...rows[1][3]],[0,255]);assert.deepEqual([...rows[2][3]],[]);assert.ok(rows.every(r=>r[4]===null));assert.equal(deletes,bound==='1'?1:0,'positive literal selects step Delete, zero and parameter retain');stmt.reset();}}finally{stmt.finalize();}assert.ok([...budgets].every(b=>b.usedBytes===0));}}finally{db.closeDeferred();}}
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;await new Promise(r=>s.close(r));}
});
