test('groups positive following flush return delete failure follows first output and preserves error cleanup',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));const del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;const budgets=new Set();const error=new Error('groups prior step deletion');let hits=0,db,stmt;PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};EphemeralIndexCursor.prototype.deleteCurrent=async function(){hits++;throw error;};
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN 1 FOLLOWING AND 9 FOLLOWING)').statement;assert.equal(await stmt.step(),'row');assert.deepEqual([stmt.column(0),stmt.column(1),stmt.column(2)],[1n,20n,5n]);assert.equal(hits,0);await assert.rejects(stmt.step(),e=>e===error);assert.equal(hits,1);assert.throws(()=>stmt.reset(),e=>e===error);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{try{stmt?.finalize()}catch{}db?.closeDeferred();EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;await new Promise(r=>s.close(r));}assert.ok([...budgets].every(b=>b.usedBytes===0));
});
test('groups retained following inverse callback failure preserves first error and cleanup',async()=>{
 const {Mem}=await import('../../src/internal/mem.ts');
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const state=Mem.prototype.aggregateState,del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;
 let armed=false,injected=0,deletes=0;const budgets=new Set();
 Mem.prototype.aggregateState=function(){const value=state.call(this);if(armed&&value?.definition?.name==='sum'&&injected===0){value.context.cnt=0n;injected++;}return value;};
 EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};
 PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN ?1 FOLLOWING AND 9 FOLLOWING)').statement;stmt.bind(1,1n);assert.equal(await stmt.step(),'row');assert.equal(await stmt.step(),'row');armed=true;let saved;
 await assert.rejects(stmt.step(),e=>{saved=e;return e.kind==='internal'&&e.message==='sum inverse without stepped value'});assert.equal(injected,1);assert.equal(deletes,0);assert.throws(()=>stmt.reset(),e=>e===saved);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{Mem.prototype.aggregateState=state;EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('groups preceding preceding streams previous peer after output before next output',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const del=EphemeralIndexCursor.prototype.deleteCurrent,insert=EphemeralIndexCursor.prototype.insert;let deletes=0,inserts=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);inserts++;};let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN 1 PRECEDING AND 1 PRECEDING)').statement;
 assert.equal(await stmt.step(),'row');assert.equal(inserts,2,'new peer admission steps and returns pending peer');const rows=[[stmt.column(0),stmt.column(1),stmt.column(2)]];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[1n,null,0n],[2n,1n,1n],[3n,2n,1n],[4n,3n,1n],[5n,4n,1n],[6n,5n,1n]]);assert.equal(deletes,4,'five stepped prior rows retire, final pending peer retained');stmt.reset();const rerun=[];while(await stmt.step()==='row')rerun.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rerun,rows);
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;EphemeralIndexCursor.prototype.insert=insert;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
