test('groups cached following flush return delete failure follows first output and preserves error cleanup',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));const del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;const budgets=new Set();const error=new Error('groups prior step deletion');let hits=0,db,stmt;PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};EphemeralIndexCursor.prototype.deleteCurrent=async function(){hits++;throw error;};
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING)').statement;assert.equal(await stmt.step(),'row');assert.deepEqual([stmt.column(0),stmt.column(1),stmt.column(2)],[1n,20n,5n]);assert.equal(hits,0);await assert.rejects(stmt.step(),e=>e===error);assert.equal(hits,1);assert.throws(()=>stmt.reset(),e=>e===error);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{try{stmt?.finalize()}catch{}db?.closeDeferred();EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;await new Promise(r=>s.close(r));}assert.ok([...budgets].every(b=>b.usedBytes===0));
});
test('groups cached retained following inverse callback failure preserves first error and cleanup',async()=>{
 const {Mem}=await import('../../src/internal/mem.ts');
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const state=Mem.prototype.aggregateState,del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;
 let armed=false,injected=0,deletes=0;const budgets=new Set();
 Mem.prototype.aggregateState=function(){const value=state.call(this);if(armed&&value?.definition?.name==='sum'&&injected===0){value.context.cnt=0n;injected++;}return value;};
 EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};
 PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};
 let db,stmt;try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN ?1 FOLLOWING AND UNBOUNDED FOLLOWING)').statement;stmt.bind(1,1n);assert.equal(await stmt.step(),'row');assert.equal(await stmt.step(),'row');armed=true;let saved;
 await assert.rejects(stmt.step(),e=>{saved=e;return e.kind==='internal'&&e.message==='sum inverse without stepped value'});assert.equal(injected,1);assert.equal(deletes,0);assert.throws(()=>stmt.reset(),e=>e===saved);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{Mem.prototype.aggregateState=state;EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('groups cached following final return delete failure follows last output and preserves error cleanup',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));const del=EphemeralIndexCursor.prototype.deleteCurrent,reserve=PrivateStateByteBudget.prototype.reserve;const budgets=new Set();const error=new Error('groups prior step deletion');let hits=0,db,stmt;PrivateStateByteBudget.prototype.reserve=function(...a){budgets.add(this);return reserve.apply(this,a);};EphemeralIndexCursor.prototype.deleteCurrent=async function(...args){hits++;if(hits===6)throw error;return del.apply(this,args);};
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d GROUPS BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING)').statement;for(let i=0;i<6;i++)assert.equal(await stmt.step(),'row');assert.deepEqual([stmt.column(0),stmt.column(1),stmt.column(2)],[6n,null,0n]);assert.equal(hits,5);await assert.rejects(stmt.step(),e=>e===error);assert.equal(hits,6);assert.throws(()=>stmt.reset(),e=>e===error);assert.ok([...budgets].every(b=>b.usedBytes===0));
 }finally{try{stmt?.finalize()}catch{}db?.closeDeferred();EphemeralIndexCursor.prototype.deleteCurrent=del;PrivateStateByteBudget.prototype.reserve=reserve;await new Promise(r=>s.close(r));}assert.ok([...budgets].every(b=>b.usedBytes===0));
});
test('range preceding following steps pending end before range-test return',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const del=EphemeralIndexCursor.prototype.deleteCurrent,insert=EphemeralIndexCursor.prototype.insert;let deletes=0,inserts=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);inserts++;};let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING)').statement;
 assert.equal(await stmt.step(),'row');assert.equal(inserts,3,'EXPLAIN64-80: step pending2, positioned end3 permits current1 return');const rows=[[stmt.column(0),stmt.column(1),stmt.column(2)]];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[1n,3n,2n],[2n,6n,3n],[3n,9n,3n],[4n,12n,3n],[5n,15n,3n],[6n,11n,2n]]);assert.equal(deletes,4,'five stepped prior rows retire, final pending peer retained');stmt.reset();const rerun=[];while(await stmt.step()==='row')rerun.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rerun,rows);
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;EphemeralIndexCursor.prototype.insert=insert;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('range following int64 shifted keys preserve adjacent row distinctions',async()=>{
 const s=http.createServer((req,res)=>{const file='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 const del=EphemeralIndexCursor.prototype.deleteCurrent,insert=EphemeralIndexCursor.prototype.insert;let deletes=0,inserts=0;EphemeralIndexCursor.prototype.deleteCurrent=async function(...a){deletes++;return del.apply(this,a);};EphemeralIndexCursor.prototype.insert=async function(...a){await insert.apply(this,a);inserts++;};let db,stmt;
 try{db=await open(new Request(`http://127.0.0.1:${s.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d + 9007199254740992 RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING)').statement;
 assert.equal(await stmt.step(),'row');const rows=[[stmt.column(0),stmt.column(1),stmt.column(2)]];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[1n,3n,2n],[2n,6n,3n],[3n,9n,3n],[4n,12n,3n],[5n,15n,3n],[6n,11n,2n]]);stmt.reset();const rerun=[];while(await stmt.step()==='row')rerun.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rerun,rows);
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=del;EphemeralIndexCursor.prototype.insert=insert;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>s.close(r));}
});
test('copied window sort expressions retain source identities for partition and ORDER in three encodings',async()=>{
 const s=http.createServer((req,res)=>{const file=`test/fixtures/aggregate-window/${req.url.slice(1)}.db`;res.writeHead(200,{'Content-Length':fs.statSync(file).size});fs.createReadStream(file).pipe(res)});await new Promise(r=>s.listen(0,'127.0.0.1',r));
 try{for(const name of ['typed','typed-utf-16le','typed-utf-16be']){
 const db=await open(new Request(`http://127.0.0.1:${s.address().port}/${name}`));
 try{for(const spec of ['ORDER BY i + 9007199254740992','PARTITION BY i % 2 ORDER BY i + 9007199254740992','PARTITION BY (i % 2) ORDER BY (i + 9007199254740992) DESC']){
 const st=db.prepare(`SELECT i,r,t,b,n,sum(r) OVER w,count(i) OVER w FROM t WINDOW w AS (${spec} RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING)`).statement;
 try{for(let pass=0;pass<2;pass++){
 const rows=[];while(await st.step()==='row')rows.push(Array.from({length:st.columnCount},(_,i)=>st.column(i)));rows.sort((a,b)=>Number(a[0]-b[0]));
 assert.deepEqual(rows.map(r=>r.slice(0,3)),[[1n,1,'A'],[2n,2.5,'a'],[3n,3,null]]);
 assert.deepEqual(rows.map(r=>r.slice(4)),spec.startsWith('PARTITION')?[[null,1,1n],[null,2.5,1n],[null,3,1n]]:[[null,3.5,2n],[null,6.5,3n],[null,5.5,2n]]);
 assert.deepEqual([...rows[0][3]],[0,255]);assert.deepEqual([...rows[1][3]],[]);assert.equal(rows[2][3],null);st.reset();
 }}finally{st.finalize();}
 }}finally{db.closeDeferred();}
 }}finally{await new Promise(r=>s.close(r));}
});

test('range pending end retires after output and preserves delete failure across reset',async()=>{
 const server=http.createServer((req,res)=>{const f='test/fixtures/aggregate-window/w2rows.db';res.writeHead(200,{'Content-Length':fs.statSync(f).size});fs.createReadStream(f).pipe(res)});await new Promise(r=>server.listen(0,'127.0.0.1',r));
 const original=EphemeralIndexCursor.prototype.deleteCurrent,error=new Error('range pending inverse deletion');let calls=0,db,stmt;
 EphemeralIndexCursor.prototype.deleteCurrent=async function(...args){if(++calls===1)throw error;return original.apply(this,args)};
 try{db=await open(new Request(`http://127.0.0.1:${server.address().port}/db`));stmt=db.prepare('SELECT a,sum(d) OVER w,count(d) OVER w FROM t1 WINDOW w AS (ORDER BY d RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING)').statement;
 assert.equal(await stmt.step(),'row');assert.deepEqual([stmt.column(0),stmt.column(1),stmt.column(2)],[1n,3n,2n]);assert.equal(calls,0,'Yield precedes inverse deletion');
 assert.equal(await stmt.step(),'row');assert.deepEqual([stmt.column(0),stmt.column(1),stmt.column(2)],[2n,6n,3n]);assert.equal(calls,0,'first prior row is still inside second frame');
 let first;try{await stmt.step();assert.fail('expected deletion error')}catch(e){first=e}assert.equal(calls,1);assert.throws(()=>stmt.reset(),e=>e===first);EphemeralIndexCursor.prototype.deleteCurrent=original;
 const rows=[];while(await stmt.step()==='row')rows.push([stmt.column(0),stmt.column(1),stmt.column(2)]);assert.deepEqual(rows,[[1n,3n,2n],[2n,6n,3n],[3n,9n,3n],[4n,12n,3n],[5n,15n,3n],[6n,11n,2n]]);
 }finally{EphemeralIndexCursor.prototype.deleteCurrent=original;try{stmt?.finalize()}catch{}db?.closeDeferred();await new Promise(r=>server.close(r));}
});
